# MOMusic 一起听服务器部署脚本
$ErrorActionPreference = "Stop"
$dir = "C:\lt-server"

Write-Host ""
Write-Host "========================================" -ForegroundColor Cyan
Write-Host "  MOMusic 一起听服务器 - 部署" -ForegroundColor Cyan
Write-Host "========================================" -ForegroundColor Cyan

# 1. 停止旧进程
Write-Host "[1/5] 停止旧服务..." -ForegroundColor Yellow
Get-Process -Name node -ErrorAction SilentlyContinue | Stop-Process -Force
Start-Sleep 2
Write-Host "  done" -ForegroundColor Green

# 2. 创建目录
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
Set-Location $dir
Write-Host "[2/5] 目录: $dir" -ForegroundColor Green

# 3. 写入文件 (base64 解码)
Write-Host "[3/5] 写入文件..." -ForegroundColor Yellow

$pkgB64 = ""
$serverB64 = ""
$ltB64 = ""

[System.IO.File]::WriteAllText("$dir\package.json", [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($pkgB64)))
[System.IO.File]::WriteAllText("$dir\listen-together-server.js", [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($serverB64)))
[System.IO.File]::WriteAllText("$dir\listen-together.js", [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($ltB64)))

Write-Host "  package.json" -ForegroundColor Green
Write-Host "  listen-together-server.js" -ForegroundColor Green
Write-Host "  listen-together.js" -ForegroundColor Green

# 4. 安装依赖
Write-Host "[4/5] 安装依赖..." -ForegroundColor Yellow
npm install --silent 2>&1 | Out-Null
Write-Host "  done" -ForegroundColor Green

# 5. 启动
Write-Host "[5/5] 启动服务器..." -ForegroundColor Cyan
Write-Host ""
node listen-together-server.js
